import{_ as i,C as l,o as a,c as r,a2 as s,b as c,w as t,a as d,E as n,a3 as h}from"./chunks/framework.DBSoX6Zw.js";const P=JSON.parse('{"title":"Architecture — GitHub Actions (.github/)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/github.md","filePath":"architecture/github.md"}'),p={name:"architecture/github.md"};function u(g,e,m,k,b,y){const o=l("Mermaid");return a(),r("div",null,[e[1]||(e[1]=s('<h1 id="architecture-—-github-actions-github" tabindex="-1">Architecture — GitHub Actions (<code>.github/</code>) <a class="header-anchor" href="#architecture-—-github-actions-github" aria-label="Permalink to &quot;Architecture — GitHub Actions (`.github/`)&quot;">​</a></h1><blockquote><p>CI/CD workflows and automation for Plik. For system-wide overview, see the root <a href="./system.html">ARCHITECTURE.md</a>.</p></blockquote><hr><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.github/</span></span>\n<span class="line"><span>├── workflows/</span></span>\n<span class="line"><span>│   ├── tests.yaml              ← CI: lint, test, docs build on push/PR</span></span>\n<span class="line"><span>│   ├── pages.yml               ← Deploy docs + publish Helm chart to gh-pages</span></span>\n<span class="line"><span>│   ├── release.yaml            ← Build release archives, Docker images on tag push</span></span>\n<span class="line"><span>│   ├── master.yaml             ← Post-merge actions on master</span></span>\n<span class="line"><span>│   ├── docker-build-pr.yaml    ← Build Docker image on PR (triggered by comment)</span></span>\n<span class="line"><span>│   └── docker-deploy-pr.yaml   ← Deploy PR image to staging (triggered by comment)</span></span>\n<span class="line"><span>├── cr.yaml                     ← chart-releaser configuration</span></span>\n<span class="line"><span>└── ARCHITECTURE.md             ← this file</span></span></code></pre></div><hr><h2 id="workflows" tabindex="-1">Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;Workflows&quot;">​</a></h2><h3 id="tests-yaml-—-ci-tests" tabindex="-1"><code>tests.yaml</code> — CI Tests <a class="header-anchor" href="#tests-yaml-—-ci-tests" aria-label="Permalink to &quot;`tests.yaml` — CI Tests&quot;">​</a></h3><p>Runs on every push and pull request. Steps:</p><ol><li>Go lint (<code>make lint</code>)</li><li>Go tests (<code>make test</code>)</li><li>Docs build (<code>make docs</code>) — verifies VitePress builds without errors</li></ol><h3 id="pages-yml-—-github-pages-docs-helm-chart" tabindex="-1"><code>pages.yml</code> — GitHub Pages (Docs + Helm Chart) <a class="header-anchor" href="#pages-yml-—-github-pages-docs-helm-chart" aria-label="Permalink to &quot;`pages.yml` — GitHub Pages (Docs + Helm Chart)&quot;">​</a></h3><p>Runs on push to <code>master</code> when <code>docs/**</code>, <code>charts/**</code>, or the workflow itself changes. Publishes <strong>two things</strong> to the <code>gh-pages</code> branch:</p><ol><li><strong>VitePress documentation</strong> — built with <code>make docs</code>, deployed via <code>peaceiris/actions-gh-pages</code></li><li><strong>Helm chart</strong> — released via <code>helm/chart-releaser-action</code>, which packages charts from <code>charts/</code> and maintains <code>index.yaml</code></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Both docs and the Helm chart share the <code>gh-pages</code> branch because GitHub Pages only supports a single publishing source. The <code>keep_files: true</code> flag in the docs deployment step preserves the Helm <code>index.yaml</code> and chart packages.</p></div><p><strong>Configuration</strong>: <code>cr.yaml</code> sets <code>skip_existing: true</code> so chart-releaser won&#39;t fail on already-released chart versions.</p><h3 id="release-yaml-—-tagged-release-pipeline" tabindex="-1"><code>release.yaml</code> — Tagged Release Pipeline <a class="header-anchor" href="#release-yaml-—-tagged-release-pipeline" aria-label="Permalink to &quot;`release.yaml` — Tagged Release Pipeline&quot;">​</a></h3><p>Triggered when a GitHub release is created (tag push). Runs the full release pipeline:</p><ol><li>Builds multi-arch Docker images</li><li>Builds release archives and client binaries</li><li>Uploads artifacts to the GitHub release</li></ol><p>See <a href="./releaser.html">releaser/ARCHITECTURE.md</a> for the build details.</p><h3 id="master-yaml-—-docker-dev-build" tabindex="-1"><code>master.yaml</code> — Docker Dev Build <a class="header-anchor" href="#master-yaml-—-docker-dev-build" aria-label="Permalink to &quot;`master.yaml` — Docker Dev Build&quot;">​</a></h3><p>Runs on every push to <code>master</code> (only in the <code>root-gg</code> org). Builds multi-arch Docker images and pushes <code>rootgg/plik:dev</code> to Docker Hub via <code>make release-and-push-to-docker-hub</code>. This ensures the <code>dev</code> tag always reflects the latest <code>master</code> state.</p><h3 id="docker-build-pr-yaml-—-pr-docker-build" tabindex="-1"><code>docker-build-pr.yaml</code> — PR Docker Build <a class="header-anchor" href="#docker-build-pr-yaml-—-pr-docker-build" aria-label="Permalink to &quot;`docker-build-pr.yaml` — PR Docker Build&quot;">​</a></h3><p>Triggered by a <code>docker build</code> comment on a PR. Builds a Docker image tagged <code>rootgg/plik:pr-{number}</code> and pushes it to Docker Hub. Reports back with a comment.</p><h3 id="docker-deploy-pr-yaml-—-pr-docker-deploy" tabindex="-1"><code>docker-deploy-pr.yaml</code> — PR Docker Deploy <a class="header-anchor" href="#docker-deploy-pr-yaml-—-pr-docker-deploy" aria-label="Permalink to &quot;`docker-deploy-pr.yaml` — PR Docker Deploy&quot;">​</a></h3><p>Triggered by a <code>docker deploy</code> comment on a PR. Deploys the PR-specific Docker image to the staging instance at <code>plik.root.gg</code>. Reports back with a deployment confirmation comment.</p><hr><h2 id="helm-chart-release-flow" tabindex="-1">Helm Chart Release Flow <a class="header-anchor" href="#helm-chart-release-flow" aria-label="Permalink to &quot;Helm Chart Release Flow&quot;">​</a></h2>',27)),(a(),c(h,null,{default:t(()=>[n(o,{id:"mermaid-114",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20Push%5B%22Push%20to%20master%3Cbr%2F%3E(charts%2F%20changed)%22%5D%20--%3E%20Pages%5B%22pages.yml%20workflow%22%5D%0A%20%20%20%20Pages%20--%3E%20BuildDocs%5B%22Build%20VitePress%20docs%22%5D%0A%20%20%20%20Pages%20--%3E%20ChartRelease%5B%22chart-releaser-action%22%5D%0A%20%20%20%20BuildDocs%20--%3E%20GHPages%5B%22gh-pages%20branch%3Cbr%2F%3E(docs%20site)%22%5D%0A%20%20%20%20ChartRelease%20--%3E%20GHPages%0A%20%20%20%20ChartRelease%20--%3E%20GitHubRelease%5B%22GitHub%20Release%3Cbr%2F%3E(chart%20.tgz)%22%5D%0A%20%20%20%20GHPages%20--%3E%20HelmRepo%5B%22helm%20repo%20add%20plik%3Cbr%2F%3Ehttps%3A%2F%2Froot-gg.github.io%2Fplik%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s(`<p>Users install the chart via:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plik</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://root-gg.github.io/plik</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plik</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plik/plik</span></span></code></pre></div><p>The chart source lives in <code>charts/plik/</code>. See the chart&#39;s <code>values.yaml</code> for all configuration options.</p>`,3))])}const C=i(p,[["render",u]]);export{P as __pageData,C as default};
